using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ChaoticAction", menuName = "Data/Battle/Battle Actions/Austra/Chaotic Action")]
public class ChaoticAction : BattleAction
{
	[Header("Dice")]
	[SerializeField]
	private RandomDicesList randomDicesList;

	[SerializeField]
	protected DicesRewardsListsList dicesRewardsListsList;

	[SerializeField]
	private bool useFixedStartingEpicPercentage;

	[SerializeField]
	[ShowIf("useFixedStartingEpicPercentage")]
	private int startingEpicPercentage;

	[SerializeField]
	private bool randomPlayerDieSentinelAction;

	public int StartingEpicPercentage => startingEpicPercentage;

	public bool RandomPlayerDieSentinelAction => randomPlayerDieSentinelAction;

	public Dice GetRandomDice(int startingEpicPercentageExternal = -1)
	{
		List<Dice> list = new List<Dice>();
		if (randomPlayerDieSentinelAction)
		{
			list = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetAllNonHexDices().Duplicate();
		}
		else
		{
			if (useFixedStartingEpicPercentage || startingEpicPercentageExternal >= 0)
			{
				DiceTier epicDiceTier = ReferenceSingleton<AssetsReference>.Instance.EpicDiceTier;
				if (CheckIfEpic(startingEpicPercentageExternal))
				{
					list = dicesRewardsListsList.GetCurrentCharacterUnlockedDiceTierDiceList(epicDiceTier).diceList.Duplicate();
					list.AddRange(dicesRewardsListsList.GetAnyCharacterUnlockedDiceTierDiceList(epicDiceTier).diceList.Duplicate());
				}
				else
				{
					list = dicesRewardsListsList.GetAllUnlockedDiceButTierCurrentCharacter(epicDiceTier).Duplicate();
					list.AddRange(dicesRewardsListsList.GetAllUnlockedDiceButTierAnyCharacter(epicDiceTier).Duplicate());
				}
			}
			else
			{
				list = dicesRewardsListsList.GetAllUnlockedDiceCurrentCharacter();
				list.AddRange(dicesRewardsListsList.GetAllUnlockedDiceAnyCharacter());
			}
			list.RemoveAll((Dice die) => randomDicesList.dice.Contains(die));
			ReferenceSingleton<AssetsReference>.Instance.DiceReward.RemoveCharactersAndChapterMutedDiceFromList(list);
		}
		return list.PickRandom(seeded: false);
	}

	public int GetEpicChanceAmount(int startingEpicPercentageExternal)
	{
		if (startingEpicPercentageExternal <= 0)
		{
			return startingEpicPercentage;
		}
		return startingEpicPercentageExternal;
	}

	private bool CheckIfEpic(int startingEpicPercentageExternal)
	{
		if (RandomUtilities.RandomChance(GetEpicChanceAmount(startingEpicPercentageExternal)))
		{
			return true;
		}
		return false;
	}
}
